  const stationHead = (title, sub, actions = '') => H.crumb(['דלתות', 'כניסה ראשית']) + H.head(title, sub, actions);
  const scheduleHead = (title, sub, actions = '') => H.crumb(['ניהול', 'ספריית לוחות', 'שעות פעילות']) + H.head(title, sub, actions);
  const detail = (pairs) => `<dl class="detail-list">${pairs.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>`;
  const label = (name, sub, glyph='door') => `<div class="person"><span class="door-glyph" style="margin:0;width:36px;height:36px">${H.icon(glyph)}</span><div><strong>${name}</strong><span class="sub">${sub}</span></div></div>`;
  const days = (active=[1,2,3,4,5]) => `<div class="week">${['א׳','ב׳','ג׳','ד׳','ה׳','ו׳','ש׳'].map((d,i)=>`<button class="day ${active.includes(i)?'on':''}" data-demo="בחירת יום בתוכנית" aria-pressed="${active.includes(i)}">${d}</button>`).join('')}</div>`;
