      <div class="card">${H.table(['תא קוד','מצב בתחנה','פעולות'],Array.from({length:6},(_,i)=>[`<strong>קוד ציבורי ${i+1}</strong>`,H.badge(i===0?'מוגדר':i===5?'לא אומת':'לא מוגדר',i===0?'good':i===5?'warn':''),i===0?`<div class="row-menu">${H.btn('החלפה','','small')}${H.btn('מחיקה','','small danger')}</div>`:i===5?'<span class="sub">נדרשת קריאה מוצלחת</span>':H.btn('הוספה','','small')]))}<div class="pagination"><span>תאים 1–6 מתוך 16</span><div class="actions">${H.btn('הקודם','','small')}${H.btn('הבא','','small')}</div></div></div>
