        ['בדיקת מוכנות','כניסה ראשית','<bdi>08:45</bdi>',H.badge('לא נתמך','warn')],
        ['הערכת תוכנית','אגף מזרח','<bdi>08:43</bdi>',H.badge('חסומה לתחנה','warn')],
        ['שמירת לוח בספרייה','כללי','<bdi>08:40</bdi>',H.badge('נשמר בספרייה')],
        ['בדיקת קריאה חוזרת','כניסת עובדים','<bdi>08:32</bdi>',H.badge('לא הושלמה','warn')],
        ['ביטול תוכנית ממתינה','אגף מערב','<bdi>אתמול, 16:20</bdi>',H.badge('בוטלה','')]
